<?php
require_once __DIR__.'/../includes/bootstrap.php';require_admin();$pdo=db();
function fixed_edit_product_size(string $categoryName): ?string {$name=strtolower(trim($categoryName));if(in_array($name,['coffee & hot drinks','hot drinks','sundae','ice cream','fruit salad'],true))return 'M';if($name==='fruit tea')return 'L';return null;}
$id=(int)($_GET['id']??$_POST['id']??0);$stmt=$pdo->prepare('SELECT * FROM products WHERE id=?');$stmt->execute([$id]);$product=$stmt->fetch();if(!$product){http_response_code(404);exit('Product not found.');}
if($_SERVER['REQUEST_METHOD']==='POST'){
  verify_csrf();
  try{$categoryId=(int)$_POST['category_id'];$catStmt=$pdo->prepare('SELECT name FROM categories WHERE id=?');$catStmt->execute([$categoryId]);$categoryName=(string)$catStmt->fetchColumn();if($categoryName==='')throw new RuntimeException('Invalid category.');$size=(string)($_POST['size']??'');$fixedSize=fixed_edit_product_size($categoryName);if($fixedSize!==null)$size=$fixedSize;if(!in_array($size,['S','M','L'],true))throw new RuntimeException('Invalid product size.');$name=trim($_POST['name']);if($name==='')throw new RuntimeException('Product name is required.');$dupe=$pdo->prepare('SELECT COUNT(*) FROM products WHERE category_id=? AND name=? AND size=? AND id<>?');$dupe->execute([$categoryId,$name,$size,$id]);if((int)$dupe->fetchColumn()>0)throw new RuntimeException('This product and size already exists.');$image=save_product_image($_FILES['image']??[],$product['image_path']?:default_product_image($categoryId));$stmt=$pdo->prepare('UPDATE products SET category_id=?,name=?,size=?,price=?,low_stock_level=?,image_path=? WHERE id=?');$stmt->execute([$categoryId,$name,$size,(float)$_POST['price'],(float)$_POST['low_stock_level'],$image,$id]);$_SESSION['flash']='Product details and photo saved.';header('Location: products.php');exit;}
  catch(Throwable $e){$error=$e->getMessage();}
}
$cats=$pdo->query('SELECT * FROM categories ORDER BY name')->fetchAll();$pageTitle='Edit Product';include __DIR__.'/../includes/header.php';
?>
<?php if(!empty($error)):?><div class="alert danger"><?=e($error)?></div><?php endif;?>
<form class="panel form-card" method="post" enctype="multipart/form-data" style="max-width:650px"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=e($id)?>">
<?php if($product['image_path']):?><div class="current-image"><img class="image-preview" src="<?=e(base_url($product['image_path']))?>" alt="<?=e($product['name'])?>"><span>Current product photo</span></div><?php endif;?>
<label>Replace Product Photo<input type="file" name="image" accept="image/jpeg,image/png,image/webp"><small>Leave empty to keep current photo. Maximum 3 MB.</small></label>
<label>Category<select name="category_id" id="editProductCategory"><?php foreach($cats as $c):?><option value="<?=e($c['id'])?>" data-fixed-size="<?=e(fixed_edit_product_size($c['name'])??'')?>" <?=$c['id']==$product['category_id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select></label><label>Product Name<input name="name" value="<?=e($product['name'])?>" required></label><label>Size<select name="size" id="editProductSize"><?php foreach(['S','M','L'] as $size):?><option <?=$size===$product['size']?'selected':''?>><?=e($size)?></option><?php endforeach;?></select></label><label>Price<input type="number" name="price" step=".01" min="0" value="<?=e($product['price'])?>" required></label><label>Low Stock Level<input type="number" name="low_stock_level" step=".01" min="0" value="<?=e($product['low_stock_level'])?>" required></label><div><button class="btn primary">Save Changes</button> <a class="btn" href="products.php">Cancel</a></div></form>
<script>const editCategory=document.getElementById('editProductCategory'),editSize=document.getElementById('editProductSize');function applyFixedEditSize(){const fixed=editCategory.options[editCategory.selectedIndex]?.dataset.fixedSize||'';Array.from(editSize.options).forEach(function(option){option.hidden=!!fixed&&option.value!==fixed;option.disabled=!!fixed&&option.value!==fixed;});if(fixed)editSize.value=fixed;}editCategory.addEventListener('change',applyFixedEditSize);applyFixedEditSize();</script>
<?php include __DIR__.'/../includes/footer.php'; ?>
